INSERT INTO espen_tables VALUES ('Afro_Regions_Summary_NTDs', '[{"Name": "WHO_REGION", "Description": "WHO region (AFRO/EMRO)"}, {"Name": "REGION", "Description": "Africa sub-region"}, {"Name": "Year", "Description": "Year"}, {"Name": "N_IU", "Description": "Number of implementation units"}, {"Name": "PopTot", "Description": "Total Population"}, {"Name": "PopPreSAC", "Description": "Total PreSAC Population"}, {"Name": "PopSAC", "Description": "Total SAC Population"}, {"Name": "PopAdult", "Description": "Total Adult Population"}, {"Name": "PC_LF", "Description": "Number of IUs that require PC for lymphatic filariasis"}, {"Name": "PC_ONC", "Description": "Number of IUs that require PC for onchocerciasis"}, {"Name": "PC_STH", "Description": "Number of IUs that require PC for STH"}, {"Name": "PC_SCH", "Description": "Number of IUs that require PC for schistosomiasis"}, {"Name": "PC_NTDs", "Description": "Number of IUs that require PC for at least 1 PC-NTDs (across all the PC NTDs except trachoma)"}, {"Name": "PC_Req", "Description": "Population requiring PC for at least one PC-NTD (across all the PC NTDs except trachoma)"}, {"Name": "PC_TH", "Description": "Number of IUs that require PC for trachoma"}, {"Name": "MDA_LF", "Description": "Number of IUs that implemented MDA against lymphatic filariasis"}, {"Name": "MDA_ONC", "Description": "Number of IUs that implemented MDA against onchocerciasis"}, {"Name": "MDA_STH", "Description": "Number of IUs that implemented MDA against STH"}, {"Name": "MDA_SCH", "Description": "Number of IUs that implemented MDA against schistosomiasis"}, {"Name": "MDA_NTDs", "Description": "Number of IUs that implemented MDA for at least 1 PC-NTDs (across all the PC NTDs except trachoma)"}, {"Name": "MDA_Trg", "Description": "Population targeted with PC for at least one NTD  (across all the PC NTDs except trachoma)"}, {"Name": "MDA_Treat", "Description": "Population treated with PC for at least one NTD (across all the PC NTDs except trachoma)"}, 