INSERT INTO espen_tables VALUES ('Afro_SCH_SiteLevel', '[{"Name": "REGION", "Description": "Africa sub-region"}, {"Name": "WHO_REGION", "Description": "WHO region (AFRO, EMRO)"}, {"Name": "COUNTRY", "Description": "Country name"}, {"Name": "COUNTRY_CODE", "Description": "Country ID"}, {"Name": "ISO2", "Description": "ISO2 code"}, {"Name": "ISO3", "Description": "ISO3 code"}, {"Name": "ADMIN1_NAME", "Description": "Name admin 1 level"}, {"Name": "ADMIN1_CODE", "Description": "Code admin 1 level"}, {"Name": "ADMIN2_NAME", "Description": "Name admin 2 level"}, {"Name": "ADMIN2_CODE", "Description": "Code admin 2 level"}, {"Name": "IU_NAME", "Description": "Name implementation unit"}, {"Name": "ESPEN_IU_ID", "Description": "ESPEN IU ID"}, {"Name": "IU_NAME_GEO", "Description": "IU where site is geolocated"}, {"Name": "IU_ID_GEO", "Description": "IU ID from area where site is located"}, {"Name": "SUB_DISTRICT", "Description": "Sub-IU Name"}, {"Name": "SUB_IU_ID", "Description": "Sub-IU ID"}, {"Name": "LOCATIONNAME", "Description": "Location name"}, {"Name": "LOCATIONTYPE", "Description": "Type survey site (school, community)"}, {"Name": "SURVEYTYPE", "Description": "Type of survey (mapping, SS, IA, etc)"}, {"Name": "LATITUDE", "Description": "Latitude"}, {"Name": "LONGITUDE", "Description": "Longitude"}, {"Name": "GEO_RELIABILITY", "Description": "0 = Site name provided but not found suitable geographical coordinates                                                                                                                                                                                                                                                                               1 = Reliable: Exact location identified (within assigned IU)\n2 = Reliable: Approx. location identified (within ADMIN1)\n3 = Unreliable: Coordinates not within the correct ADM1 boundary (but within assigned country)                                                                               