INSERT INTO espen_tables VALUES ('Afro_STH_SiteLevel', '[{"Name": "Source", "Description": "Source of site level data: AFRO (NTD mapping project) ;GAHI (Global Atlas of Helminth Infections) or SCI (Schistosomiasis Control Initiative)"}, {"Name": "WHO_REGION", "Description": "African region"}, {"Name": "Region", "Description": "WHO Africa region"}, {"Name": "Country", "Description": "Country Name"}, {"Name": "ISO3", "Description": "ISO code 3"}, {"Name": "ISO2", "Description": "ISO code 2"}, {"Name": "ADMIN1", "Description": "ADMIN 1 name"}, {"Name": "ADMIN1ID", "Description": "ADMIN 1 ID"}, {"Name": "ADMIN2", "Description": "ADMIN 2 name"}, {"Name": "ADMIN2ID", "Description": "ADMIN 2 ID"}, {"Name": "IU_NAME", "Description": "Name of IU at 2018 (according to current ESPEN IU layer)"}, {"Name": "IU_ID", "Description": "IU ID at 2018"}, {"Name": "Location", "Description": "Location name"}, {"Name": "SiteID", "Description": "Site ID  (assigned by NTD mapping project)"}, {"Name": "Longitude", "Description": "Longitude"}, {"Name": "Latitude", "Description": "Latitude"}, {"Name": "georeliability", "Description": "1 = Reliable: Exact location identified on Google Maps\n2 = Reliable: Approx. location identified on Google Maps\n3 = Reliable: Coordinates located within the correct ADM1 boundary\n4 = Unreliable: Coordinates not within the correct ADM1 boundary\n99 = Not found: Location could not be georeferenced"}, {"Name": "LocationType", "Description": "School, village, area, etc."}, {"Name": "Year", "Description": "Survey year"}, {"Name": "Month", "Description": "Survey month"}, {"Name": "Age_start", "Description": "Age start"}, {"Name": "Age_end", "Description": "Age end"}, {"Name": "HK_examined", "Description": "Number of individuals sampled for Hookworm infection"}, {"Name": "HK_positive", "Description": "Number of children positive for Hookworm infection"}, {"Name": "HK_prevalence", "Description": "Estimated Hookworm prevalence  (n positive/ n examined)"}, {"Name": "HK_